WITH with_windows AS (SELECT *, ROW_NUMBER() OVER (ORDER BY started_at, id) AS seq_no, FIRST_VALUE(country) IGNORE NULLS OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_country, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY started_at DESC, id) AS event_seq, FIRST_VALUE(country) IGNORE NULLS OVER (PARTITION BY device, customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_country_2, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at, id) AS event_seq_2 FROM sessions) SELECT DATE_TRUNC('QUARTER', started_at) AS quarter_start, browser, DATE_TRUNC('MONTH', started_at) AS activity_month, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, ROUND(AVG(event_seq), 2) AS avg_event_seq, MAX(started_at) AS last_started_at, ROUND(SUM(event_seq) / NULLIF(COUNT(CASE WHEN country = 'JP' THEN 1 END), 0), 2) AS event_seq_per_jp, COUNT(CASE WHEN browser = 'Chrome' THEN 1 END) AS chrome_count, COUNT(*) FILTER (WHERE browser = 'Safari') AS safari_rows FROM with_windows GROUP BY DATE_TRUNC('QUARTER', started_at), browser, DATE_TRUNC('MONTH', started_at) ORDER BY safari_rows DESC NULLS FIRST;
